package com.repairconnect.controller; import com.repairconnect.entity.ServiceCategory; import com.repairconnect.repository.ServiceCategoryRepository; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/categories") public class CategoryController {private final ServiceCategoryRepository repo; public CategoryController(ServiceCategoryRepository r){repo=r;} @GetMapping List<ServiceCategory> all(){return repo.findAll();} @PostMapping @PreAuthorize("hasRole('ADMIN')") ServiceCategory add(@RequestBody ServiceCategory c){return repo.save(c);} @PutMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") ServiceCategory edit(@PathVariable Long id,@RequestBody ServiceCategory c){var old=repo.findById(id).orElseThrow();old.setName(c.getName());old.setDescription(c.getDescription());old.setActive(c.isActive());return repo.save(old);} @DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") void delete(@PathVariable Long id){repo.deleteById(id);} }